  static ThemeData _build(KdTokens t, Brightness brightness) {
    final colorScheme = ColorScheme(
      brightness: brightness,
      primary: t.colorAccent,
      onPrimary: t.colorOnAccent,
      secondary: t.colorAccent,
      onSecondary: t.colorOnAccent,
      error: t.colorError,
      onError: t.colorOnError,
      surface: t.surfaceRaised,
      onSurface: t.textDefault,
      onSurfaceVariant: t.textMuted,
      surfaceContainerLowest: t.surfaceSunken,
      surfaceContainerLow: t.surfaceBase,
      surfaceContainer: t.surfaceRaised,
      surfaceContainerHigh: t.surfaceOverlay,
      surfaceContainerHighest: t.surfaceOverlay,
      outline: t.borderStrong.color,
      outlineVariant: t.borderHairline.color,
    );
    final textTheme = TextTheme(
      headlineMedium: t.typeDisplay,
      titleLarge: t.typeTitle,
      titleMedium: t.typeSubtitle,
      bodyLarge: t.typeBody,
      bodyMedium: t.typeBody,
      bodySmall: t.typeBodySm,
      labelLarge: t.typeLabel,
      labelMedium: t.typeLabel,
      labelSmall: t.typeCaption,
    ).apply(bodyColor: t.textDefault, displayColor: t.textDefault);

    return ThemeData(
      useMaterial3: true,
      brightness: brightness,
      colorScheme: colorScheme,
      scaffoldBackgroundColor: t.surfaceBase,
      canvasColor: t.surfaceBase,
      focusColor: t.colorFocus,
      dividerTheme: DividerThemeData(
        color: t.borderHairline.color,
        thickness: t.borderHairline.width,
      ),
      textTheme: textTheme,
      materialTapTargetSize: MaterialTapTargetSize.padded,
      extensions: <ThemeExtension<dynamic>>[t],
    );
  }
}
